340-  const was = await shown(r.getByTestId('person-statement-count'));
341-  await r.getByTestId('person-statement').click();
342-  return until(page, async () => await shown(r.getByTestId('person-statement-count')) !== was,
343-    r.getByTestId('person-error'), 'statement');
344-}
