346-/** Take the person's statement as of a date: true once the statement count has moved on. */
347-export async function statementAsOf(page: Page, personId: string, date: string): Promise<boolean> {
348-  const r = row(page, personId);
349-  const was = await shown(r.getByTestId('person-statement-count'));
350-  await r.getByTestId('person-statement-asof').fill(date);
351-  await r.getByTestId('person-statement').click();
352-  return until(page, async () => await shown(r.getByTestId('person-statement-count')) !== was,
