        }
        Sheet then = at(now.getId(), asOf).map(AsOf::sheet)
                .orElseGet(() -> now.asOf(asOf, List.of(), null));
        then.setArchived(views(now.getId(), asOf).orElse(Views.EMPTY).archived());
        return then;
